import numpy as np, wave, subprocess, sys, os
SR=44100
def call(name, args):
    r=subprocess.run(['ft2','call',name,json.dumps(args)],capture_output=True,text=True)
    return r.stdout.strip()
import json
def render_and_measure(cells, bpm=60, speed=6, rows=None, path='work/pr.wav'):
    call('module_new',{'channels':4,'name':'pr'})
    call('song_set',{'bpm':bpm,'speed':speed,'length':1,'channels':4})
    call('order_set',{'position':0,'pattern':0})
    for inst, rel in [(1,None)]:
        pass
    # cells: list of dicts with instrument path etc.
    return path

def measure(path, sr=44100):
