{"command": "mkdir -p /workspace/work/s && cat > /workspace/work/synth.py <<'PYEOF'
import numpy as np, math
SR = 44100
C_CONST = 1.01253
K_NATIVE = 78.0

SEMI = {'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
def N(name):
    name=name.strip()
    for k in ['C#','D#','F#','G#','A#']:
        if name.startswith(k):
            s=SEMI[k]; rest=name[len(k):]; break
    else:
        s=SEMI[name[0]]; rest=name[1:]
    return int(rest)*12 + s + 1
def NF(n): return 440.0*2.0**((n-70)/12.0)
def rate(play, rel=0.0): return SR*2.0**((play+rel-K_NATIVE)/12.0)*C_CONST
def f0(target, play, rel=0.0): return target/(2.0**((play+rel-K_NATIVE)/12.0)*C_CONST)

def _wave(kind, ph):
    if kind=='sine': return np.sin(2*np.pi*ph)
    if kind=='saw':  return 2*ph-1
    if kind=='square': return np.where(ph<0.5,1.0,-1.0)
    if kind=='tri':  return 4*np.abs(ph-0.5)-1
    if kind=='nsaw': return 2*ph-1
    raise ValueError(kind)

def additive(comps, n, sr=SR):
    t=np.arange(n)/sr
    out=np.zeros(n)
    for f,a,kind in comps:
        out += a*_wave(kind,(f*t)%1.0)
    return out

def env_pluck(n, attack, tau, end=0.0):
    t=np.arange(n)/SR
    e=np.minimum(1.0, t/max(attack,1e-6))
    e*=np.exp(-t/tau)
    e*= (1.0-end)
    return e

def env_sustain(n, attack, hold=0.7, tail=0.3, end=0.0):
    """attack ramp, hold level, then linear decay to end"""
    t=np.arange(n)/SR
    e=np.ones(n)
    a=max(attack,1e-6)
    e*=np.minimum(1.0,t/a)
    # hold then decay
    dur=n/SR
    dec_start=dur*tail
    m=t>dec_start
    e[m]=np.maximum(end, 1.0-(t[m]-dec_start)/(dur-dec_start)*(1.0-end))
    return e*hold + e*0  # keep simple

def normalize(x, peak=0.85):
    m=np.abs(x).max()
    if m>0: x=x*(peak/m)
    return x

def to_i16(x):
    return np.clip(x,-1,1)

def write_wav(path, x, peak=0.85):
    x=normalize(np.asarray(x,float),peak)
    d=(x*32767).astype(np.int16)
    import wave
    w=wave.open(path,'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR)
    w.writeframes(d.tobytes()); w.close()
    return len(d)
PYEOF
echo ok"}

